        'composer' => 'Alexander Maksimov, Alexey Aigi',
        'production_designer' => 'Vladimir Namestnikov, Ivan Lungin, Vitaly Trukhanenko',
        'cast' => 'Victoria Isakova, Pavel Trubiner, Alexander Baluev, Bogdan Stupka, Yuri Chursin, Andrey Krasko, Sergey Makhovikov, Alexey Gorbanov, Alexey Lapshin, Grigory Perl, Maria Shalaeva',
